const normalizeSem = (semStr) => {
  if (!semStr) return "3rd Sem";
  const s = String(semStr).trim();
  const m = s.match(/([1-8])/);
  if (!m) return s;
  const num = m[1];
  const sufs = { "1": "st", "2": "nd", "3": "rd" };
  return `${num}${sufs[num] || "th"} Sem`;
};
const normalizeDiv = (divStr) => {
  if (!divStr) return "Div 1";
  const s = String(divStr).trim();
  const m = s.match(/([1-9])/);
  if (!m) return s;
  return `Div ${m[1]}`;
};
